css:
.tiles{display:grid; grid-template-columns:repeat(48,8px); grid-auto-rows:8px; gap:2px}
.tiles i{grid-area:var(--r)/var(--c)/span var(--rs)/span var(--cs); background:#f0a0bd}
.tiles i.g{background:#d8d8d8}
/* 高さを揃えず下端だけ合わせる */
.cols{display:grid; grid-template-columns:repeat(3,1fr); align-items:start}
.cols h3{min-height:150px; display:grid; align-content:end; justify-items:center}
.h-coe{letter-spacing:.5em; line-height:1.15; font-size:34px}
.h-kids{font-size:40px}
